entities.name:
[[[
  var name = 'DETAILS OF LAST RUN';
  if (name == 'DETAILS OF LAST RUN' &&
      (
      states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle2_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle3_running'].state == 'on'
      )
    )
    return 'DETAILS OF THIS RUN';
  else
    return name;
]]]

[[[
  var previous_run_date = states['input_text.irrigation_previous_run_date'].state;
  var previous_run_time = states['input_text.irrigation_previous_run_time'].state;

  var year = new Date();
  var today = new Date();
  var yesterday = new Date(Date.now() - 86400000);

  year = year.getFullYear();

  today = today.toDateString();
  today = Date.parse(today);

  yesterday = yesterday.toDateString();
  yesterday = Date.parse(yesterday);

  if (today == Date.parse(previous_run_date + ' ' + year))
     return 'Today at ' + previous_run_time + '&nbsp-&nbsp';
  else if (yesterday == Date.parse(previous_run_date + ' ' + year))
     return 'Yesterday at ' + previous_run_time + '&nbsp-&nbsp';
  else
    return previous_run_date + 
          ' at ' + 
          previous_run_time +
          '&nbsp-&nbsp';
]]]

entities.label:
[[[
  return states['input_text.irrigation_previous_run_cycle_name'].state  + ' Cycle'
]]]

entities.name:
[[[
  var raw = entity?.state;
  var total_seconds = Number(raw);
  if (raw == null || String(raw).trim() === '' || !Number.isFinite(total_seconds) || total_seconds < 0)
    return '—';
  var hours = Math.floor(total_seconds / 3600);
  var minutes = Math.floor(total_seconds % 3600 / 60);
  var seconds = Math.floor(total_seconds % 60);
  return [hours, minutes, seconds].map(v => String(v).padStart(2, '0')).join(':');
]]]

[[[
  var zone = 'zone1';
  return states['input_text.irrigation_' + zone + '_name'].state + '&nbsp-&nbsp';
]]]

entities.label:
[[[
  if (entity.state === '')
    return '';
  else if (isNaN(entity.state))
    return entity.state;
  else 
    var total_seconds = parseFloat(entity.state);
    var minutes = Math.floor(total_seconds / 60);
    var seconds = (total_seconds % 60).toFixed();
    while (seconds.length < 2) {seconds = "0" + seconds};
    return minutes + "m " + seconds + 's';
]]]

card.display:
[[[
  var zone = 'zone1';
  zone = Number(zone.replace('zone', ''));
  var number_of_zones = Number(states['input_number.irrigation_number_of_zones'].state);
  var show_details = states['input_boolean.irrigation_ui_show_last_run_details'].state;
  if (zone > number_of_zones ||
      show_details == 'off')
    return 'none';
  else return null;
]]]

