card_mod.style:
ha-card {
  background: none;
}
#states {

  {% set show = states('input_boolean.irrigation_ui_show_last_run_details') %}
  {% if show == 'off' %}
    display: none;
  {% endif %}

  padding-top: 0em;
  padding-bottom: 0em;
}

entities.name:
[[[
  var name = 'HISTORY TOTALS (approx<br>due to history sensor)';
  if (name == 'DETAILS OF LAST RUN' &&
      (
      states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle2_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle3_running'].state == 'on'
      )
    )
    return 'DETAILS OF THIS RUN';
  else
    return name;
]]]

card.display:
[[[
  var zone = 'zone1';
  zone = Number(zone.replace('zone', ''));
  var number_of_zones = Number(states['input_number.irrigation_number_of_zones'].state);
  var show_history = states['input_boolean.irrigation_ui_show_status_history'].state;
  if (zone > number_of_zones ||
      show_history == 'off' )
    return 'none';
  else return null;
]]]

custom_fields.total_yesterday:
[[[
  var zone = 'zone1';
  var duration = states['sensor.irrigation_' + zone + '_total_time_yesterday']?.state;
  if (!Number.isFinite(Number(duration)) || duration === '') return '—';
  var duration_s = parseFloat(duration) * 3600;
  var h = Math.floor(duration_s / 3600);
  var m = Math.floor(duration_s % 3600 / 60);
  var s = Math.floor(duration_s % 3600 % 60);

  var hDisplay = h > 0 ? h + "h " : "";
  var mDisplay = h > 0 ? m + "m " : m > 0 ? m + "m " : ""; 
  var sDisplay = s + "s ";

  return hDisplay + mDisplay + sDisplay;
]]]

