  if (states['timer.irrigation_zone1_timer'].state == 'active')
    return 'zone1';
  else if (states['timer.irrigation_zone2_timer'].state == 'active')
    return 'zone2';
  else if (states['timer.irrigation_zone3_timer'].state == 'active')
    return 'zone3';
