card.display:
[[[
  var cycle = '1';
  if (cycle != '3') return 'none';
]]]

cards.name:
[[[
  var start_time = new Date(null);
  var raw = entity?.state;
  var start_time_seconds = Number(raw);
  if (raw == null || String(raw).trim() === '' || !Number.isFinite(start_time_seconds))
    return 'Start Time: —';

  start_time.setSeconds(start_time_seconds);

  return "Start Time: " + start_time.toISOString().substr(11, 5);    
]]]

cards.label:
[[[
  var cycle = '1';
  var end_time = new Date(null);
  var raw_start = states['sensor.irrigation_cycle' + cycle + '_start_time_in_seconds']?.state;
  var raw_duration = states['sensor.irrigation_cycle' + cycle + '_duration_in_seconds']?.state;
  if ([raw_start, raw_duration].some(v => v == null || String(v).trim() === '' || !Number.isFinite(Number(v))))
    return '';
  var start_time = Number(raw_start);
  var duration = Number(raw_duration);
  var total_seconds = start_time + duration;

  end_time.setSeconds(total_seconds);

  return "<br>(Will end about " + end_time.toISOString().substr(11, 5) + ")";    
]]]

cards.name:
[[[
  var zone = '1';
  if (entity.state == 'off' &&
      states['input_boolean.irrigation_cycle1_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle2_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle3_running'].state == 'off')
    return 'Run This Zone Now';
  else if (
          entity.state == 'on' &&
          states['timer.irrigation_zone' + zone + '_timer'].state == 'active'
          )
    return 'Stop This Zone';
  else return '';
]]]

cards.icon:
[[[
  var zone = '1';
  if (entity.state == 'off' &&
      states['input_boolean.irrigation_cycle1_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle2_running'].state == 'off' &&
      states['input_boolean.irrigation_cycle3_running'].state == 'off')
    return 'mdi:play-circle-outline';
  else if (
          entity.state == 'on' &&
          states['timer.irrigation_zone' + zone + '_timer'].state == 'active'
          )
    return 'mdi:stop-circle-outline';
  else return '';
]]]

card.display:
[[[
  var zone = '1';
  if (states['input_select.irrigation_cycle'].state != 'cycle3')
    return 'none';
  else if (states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
          states['input_boolean.irrigation_cycle2_running'].state == 'on')
    return 'none';
  else if (
          entity.state == 'on' &&
          states['timer.irrigation_zone' + zone + '_timer'].state != 'active'
          )
    return 'none';
  else return '';
]]]

card.border:
[[[
  var zone = '1';
  if (entity.state == 'on' &&
      states['input_boolean.irrigation_cycle1_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle2_running'].state == 'on' ||
      states['input_boolean.irrigation_cycle3_running'].state == 'on')
    return ''; 
  else return '1px solid var(--accent-color)';
]]]

card.padding:
[[[
  var zone = '1';
  if (entity.state == 'on' ||
