  var start_time_seconds = Number(raw);
  if (raw == null || String(raw).trim() === '' || !Number.isFinite(start_time_seconds))
    return 'Start Time: —';

  start_time.setSeconds(start_time_seconds);

  return "Start Time: " + start_time.toISOString().substr(11, 5);    
]]]

cards.label:
[[[
  var cycle = '2';
  var end_time = new Date(null);
  var raw_start = states['sensor.irrigation_cycle' + cycle + '_start_time_in_seconds']?.state;
  var raw_duration = states['sensor.irrigation_cycle' + cycle + '_duration_in_seconds']?.state;
  if ([raw_start, raw_duration].some(v => v == null || String(v).trim() === '' || !Number.isFinite(Number(v))))
    return '';
  var start_time = Number(raw_start);
  var duration = Number(raw_duration);
  var total_seconds = start_time + duration;

  end_time.setSeconds(total_seconds);

  return "<br>(Will end about " + end_time.toISOString().substr(11, 5) + ")";    
]]]

