cards.name:
[[[
  var raw = states['sensor.irrigation_cycle3_duration_in_seconds']?.state;
  var total_seconds = Number(raw);
  if (raw == null || String(raw).trim() === '' || !Number.isFinite(total_seconds) || total_seconds < 0)
    return 'Total Runtime: —';
  var hrs = Math.floor(total_seconds / 3600);
  var mins = String(Math.floor(total_seconds % 3600 / 60)).padStart(2, '0');

  if (hrs == 1)
    var hrs_s = ' Hour and ';
  else
    var hrs_s = ' Hours and ';

  if (mins == 1)
    var mins_s = ' Minute';
  else
    var mins_s = ' Minutes';

  if (states['input_boolean.irrigation_testing_mode'].state == 'on')
    return 'Total Runtime: ' + total_seconds + ' Seconds (testing mode)';
  else {
    if (hrs == 0)
      return 'Total Runtime: ' + (total_seconds / 60) + mins_s;
    else
      return 'Total Runtime: ' + hrs + hrs_s + mins + mins_s;
  }
]]]

